<?php $pageTitle='Contact'; include 'header.php'; ?><main class="wrap section contact-layout"><div><p class="eyebrow">SAY HELLO</p><h1>Contact Us</h1><p>Have a question or want to share feedback? Send us a message!</p><p><strong>Location:</strong> Bronx, New York</p><p class="note">This is a student project; no physical restaurant or public contact email is provided.</p></div><div class="form-card"><h2>Send a message</h2><?php if (isset($_GET['sent']) && $_GET['sent']==='1'): ?><p class="success" role="status">Thank you! Your message was saved.</p><?php elseif (isset($_GET['error'])): ?><p class="error" role="alert">Please check your information and try again.</p><?php endif; ?><form method="post" action="save_contact.php"><label for="name">Name</label><input id="name" name="name" maxlength="100" required><label for="email">Email</label><input id="email" name="email" type="email" maxlength="150" required><label for="subject">Subject</label><input id="subject" name="subject" maxlength="150" required><label for="message">Message</label><textarea id="message" name="message" rows="5" maxlength="2000" required></textarea><button class="button" type="submit">Send Message</button></form></div></main><?php include 'footer.php'; ?>